static void arm_bx(arm7tdmi_t* cpu, u32 opcode) {
    cpu->r[15] = cpu->r[opcode & 0xF];
    cpu->thumb_mode = (cpu->r[15] & 0b1);
    cpu->r[15] &= 0xFFFFFFFE;
    arm7tdmi_pipeline_refill(cpu);
}

static void arm_b_bl(arm7tdmi_t* cpu, u32 opcode) {
    bool link_bit = (opcode >> 24) & 1;
    bool sign = (opcode >> 23) & 1;

    if (link_bit) {
        cpu->r[14] = cpu->r[15] - 4;
    }

    u32 offset = opcode & 0xFFFFFF;
    if (sign)
        offset |= 0xFF000000;
    offset <<= 2;

    cpu->r[15] += offset;
    arm7tdmi_pipeline_refill(cpu);
}

static void arm_mrs(arm7tdmi_t* cpu, u32 opcode) {
    bool p_bit = (opcode >> 22) & 1;

    if (p_bit)
        cpu->r[(opcode >> 12) & 0xF] = *getSPSR(cpu);
    else
        cpu->r[(opcode >> 12) & 0xF] = cpu->CPSR;
}

static void arm_msr(arm7tdmi_t* cpu, u32 opcode) {
    bool p = (opcode >> 22) & 1;
    bool i_bit = (opcode >> 25) & 1;
    
    u32 operand;
    u8 field_mask = (opcode >> 16) & 0xF;
    u32 mask = 0;
    
    if (field_mask & 0b1000)
        mask |= 0xFF000000;
    if (field_mask & 0b1)
        mask |= 0xFF;

    if (!i_bit) 
        operand = cpu->r[opcode & 0xF];
    else
        operand = roller_imm(cpu, opcode, false);

    if (p) {
        u32* spsr = getSPSR(cpu);
        *spsr = (*spsr & ~mask) | (operand & mask);
    } else {
        saveBankedReg(cpu);
        cpu->CPSR = (cpu->CPSR & ~mask) | (operand & mask);
        loadBankedReg(cpu);
    }
}

static void arm_data_processing(arm7tdmi_t* cpu, u32 opcode) {
    bool s_bit = (opcode >> 20) & 1;
    bool i_bit = (opcode >> 25) & 1;
    u8 op4 = (opcode >> 21) & 0xF;
    u32 bit456 = (opcode >> 4) & 0b111;

    u8 rd_idx = (opcode >> 12) & 0xF;
    u8 rn_idx = (opcode >> 16) & 0xF;
    u32 rn = cpu->r[rn_idx];
    u32* rd = &cpu->r[rd_idx];
    u32 op2;
    
    bool old_carry = cpu->C_FLAG;

    if (i_bit) {
        op2 = roller_imm(cpu, opcode, s_bit);
    } else {
        op2 = shifter_reg(cpu, opcode, s_bit);
        if (bit456 & 1) {
            if (rn_idx == 15)
                rn += 4;
        }
    }

    if (op4 == 0x4 || op4 == 0x2 || op4 == 0x5 || op4 == 0x6 || op4 == 0x3 || op4 == 0x7)
        cpu->C_FLAG = old_carry;

    switch (op4) {
        case 0x0: alu_AND(cpu, rd, rn, op2, s_bit); break;
        case 0x1: alu_EOR(cpu, rd, rn, op2, s_bit); break;
        case 0x2: alu_SUB(cpu, rd, rn, op2, s_bit); break;
        case 0x3: alu_RSB(cpu, rd, rn, op2, s_bit); break;
        case 0x4: alu_ADD(cpu, rd, rn, op2, s_bit); break;
        case 0x5: alu_ADC(cpu, rd, rn, op2, s_bit); break;
        case 0x6: alu_SBC(cpu, rd, rn, op2, s_bit); break;
        case 0x7: alu_RSC(cpu, rd, rn, op2, s_bit); break;
        case 0x8: alu_TST(cpu, rd, rn, op2, s_bit); break;
        case 0x9: alu_TEQ(cpu, rd, rn, op2, s_bit); break;
        case 0xA: alu_CMP(cpu, rd, rn, op2, s_bit); break;
        case 0xB: alu_CMN(cpu, rd, rn, op2, s_bit); break;
        case 0xC: alu_ORR(cpu, rd, rn, op2, s_bit); break;
        case 0xD: alu_MOV(cpu, rd, rn, op2, s_bit); break;
        case 0xE: alu_BIC(cpu, rd, rn, op2, s_bit); break;
        case 0xF: alu_MVN(cpu, rd, rn, op2, s_bit); break;
    }

    if (s_bit) {
        if (rd_idx == 15) {
            saveBankedReg(cpu);
            cpu->CPSR = *getSPSR(cpu);
            loadBankedReg(cpu);
        }
    }
    
    if (op4 != 0xA && op4 != 0xB && op4 != 0x8 && op4 != 0x9) {
        if (rd_idx == 15)
            arm7tdmi_pipeline_refill(cpu);
    }
}

static void arm_halfword_data_transfer(arm7tdmi_t* cpu, u32 opcode) {
    bool load_bit = (opcode >> 20) & 1;
    bool write_bit = (opcode >> 21) & 1;
    bool opcodeBit22 = (opcode >> 22) & 1;
    bool up_bit = (opcode >> 23) & 1;
    bool pre_bit = (opcode >> 24) & 1;
    u8 op2 = (opcode >> 5) & 0b11;

    u32 offset;
    u32* rd = &cpu->r[(opcode >> 12) & 0xF];
    u32* rn = &cpu->r[(opcode >> 16) & 0xF];

    if (opcodeBit22)
        offset = (opcode & 0xF) | (((opcode >> 8) & 0xF) << 4);
    else {
        offset = cpu->r[opcode & 0xF];
    }

    u32 addr = *rn;

    if (pre_bit)
        addr += up_bit ? offset : -offset;

    switch (op2) {
        case 0x00:
        alu_SWP(cpu, opcode);
        return;
        
        case 0x01:
        if (load_bit) {
            *rd = readHalfWordAndTick(cpu, addr, false);
            if (addr & 1)
                *rd = (*rd >> 8) | (*rd << 24);
            cpu->cycles += I_CYCLES;
            cpu->fetch_seq = false;
        } else {
            cpu->fetch_seq = false;
            writeHalfWordAndTick(cpu, addr, *rd, false);
        }
        break;
        
        case 0x02:
        if (load_bit) {
            *rd = readByteAndTick(cpu, addr, false);
            if (*rd & 0x80)
                *rd |= 0xFFFFFF00; 
        } else {
            cpu->fetch_seq = false;
            writeByteAndTick(cpu, addr, *rd, false);
        }
        break;
        
        case 0x03:
        if (load_bit) {
            *rd = readHalfWordAndTick(cpu, addr, false);
            if (*rd & 0x8000)
                *rd |= 0xFFFF0000;
            if (addr & 1)
                *rd = (*rd >> 8) | (*rd & 0x00800000 ? 0xFF000000 : 0);
        } else {
            cpu->fetch_seq = false;
            writeHalfWordAndTick(cpu, addr, *rd, false);
        }
        break;
    }

    if (!pre_bit)
        addr += up_bit ? offset : -offset;

    if (write_bit || !pre_bit) {
        if (!load_bit)
            *rn = addr;
        else {
            if (rn != rd)
                *rn = addr;
        }
    }
}

static void arm_single_data_transfer(arm7tdmi_t* cpu, u32 opcode) {
    bool i_bit = (opcode >> 25) & 1;
    bool p_bit = (opcode >> 24) & 1;
    bool u_bit = (opcode >> 23) & 1;
    bool b_bit = (opcode >> 22) & 1;
    bool w_bit = (opcode >> 21) & 1;
    bool l_bit = (opcode >> 20) & 1;
    
    u32 rn_idx = (opcode >> 16) & 0xF;
    u32 rd_idx = (opcode >> 12) & 0xF;
    u32* rn = &cpu->r[rn_idx];
    u32* rd = &cpu->r[rd_idx];
    u32 addr = *rn;
    u32 offset;

    if (i_bit) {
        offset = shifter_reg(cpu, opcode, false);
    } else {
        offset = opcode & 0xFFF;
    }

    if (p_bit)
        addr += u_bit ? offset : -offset;

    if (l_bit) {
        if (b_bit) {
            *rd = readByteAndTick(cpu, addr, false);
            cpu->cycles += I_CYCLES;
            cpu->fetch_seq = false;
        } else {
            *rd = readWordAndTick(cpu, addr, false);
            *rd = alu_ROR(cpu, *rd, (addr & 0b11) << 3, false);
            cpu->cycles += I_CYCLES;
            cpu->fetch_seq = false;
            if (rd_idx == 15)
                arm7tdmi_pipeline_refill(cpu);
        }
    } else {
        cpu->fetch_seq = false;
        u32 val = *rd;
        if (rd_idx == 15)
            val += 4;
        if (b_bit)
            writeByteAndTick(cpu, addr, val, false);
        else
            writeWordAndTick(cpu, addr, val, false);
    }

    if (!p_bit)
        addr += u_bit ? offset : -offset;

    if (w_bit || !p_bit) {
        if (!l_bit)
            *rn = addr;
        else {
            if (rn != rd)
                *rn = addr;
        }
    }
}

static void arm_block_data_transfer(arm7tdmi_t* cpu, u32 opcode) {
    bool p_bit = (opcode >> 24) & 1;
    bool u_bit = (opcode >> 23) & 1;
    bool s_bit = (opcode >> 22) & 1;
    bool w_bit = (opcode >> 21) & 1;
    bool l_bit = (opcode >> 20) & 1;
    bool bit15 = (opcode >> 15) & 1;

    u8 base_idx = (opcode >> 16) & 0xF;
    u32* rn = &cpu->r[base_idx];
    u16 reg_list = opcode & 0xFFFF;
    u32* regs = cpu->r;
    u32 addr = *rn;

    if (!bit15 && s_bit) {
        saveBankedReg(cpu);
        regs = cpu->usr_r;
    }

    u32 reg_count = __builtin_popcount(reg_list);
    if (!u_bit) {
        addr -= reg_count * 4;
        p_bit ^= 1;
    }

    cpu->fetch_seq = false;

    if (!reg_count) {
        if (l_bit) {
            cpu->r[15] = readWordAndTick(cpu, *rn, false);
            arm7tdmi_pipeline_refill(cpu);
        } else {
            if (!u_bit)
                writeWordAndTick(cpu, *rn - (p_bit ? 0x3C : 0x40), cpu->r[15] + 4, false);
            else
                writeWordAndTick(cpu, *rn + (p_bit ? 0x04 : 0x00), cpu->r[15] + 4, false);
        }
        if (!u_bit)
            cpu->r[base_idx] -= 0x40;
        else
            cpu->r[base_idx] += 0x40;
    } else {
        bool first_transfer = true;
        for (int i = 0; i < 16 && reg_list; i++) {
            bool should_transfer = reg_list & 1;
            reg_list >>= 1;
            if (!should_transfer)
                continue;

            if (p_bit)
                addr += 4;

            if (l_bit) {
                regs[i] = readWordAndTick(cpu, addr, !first_transfer);
                if (i == 15) {
                    arm7tdmi_pipeline_refill(cpu);
                    if (s_bit) {
                        printf("S BIT ON ARM PUSH/POP NOT IMPLEMENTED\n");
                    }
                }
            } else {
                if (i == base_idx && !first_transfer) {
                    if (!u_bit)
                        writeWordAndTick(cpu, addr, *rn - (reg_count << 2), false);
                    else
                        writeWordAndTick(cpu, addr, *rn + (reg_count << 2), false);
                } else
                    writeWordAndTick(cpu, addr, i == 15 ? regs[i] + 4 : regs[i], false);
            }

            if (!p_bit)
                addr += 4;
            
            first_transfer = false;
        }

        if (!u_bit)
            addr -= reg_count * 4;

        reg_list = opcode & 0xFFFF;
        if (!(bit15) && s_bit)
            loadBankedReg(cpu);

        if (w_bit) {
            if (!l_bit)
                *rn = addr;
            else {
                if (!(reg_list & (1 << base_idx)))
                    *rn = addr;
            }
        }
    }

    if (l_bit)
        cpu->cycles += I_CYCLES;
}

static void arm_multiply(arm7tdmi_t* cpu, u32 opcode) {
    bool a = (opcode >> 21) & 1;
    bool s = (opcode >> 20) & 1;
    
    u32 rm = cpu->r[opcode & 0xF];
    u32 rs = cpu->r[(opcode >> 8) & 0xF];
    u32 rn = cpu->r[(opcode >> 12) & 0xF];
    u32* rd = &cpu->r[(opcode >> 16) & 0xF];
    
    *rd = ((i32)rm) * ((i32)rs);
    
    if (a) {
        *rd += rn;
    }

    if (!(rs & 0xFFFFFF00) || !((~rs) & 0xFFFFFF00))
        cpu->cycles += a ? 2 : 1;
    else if (!(rs & 0xFFFF0000) || !((~rs) & 0xFFFF0000))
        cpu->cycles += a ? 3 : 2;
    else if (!(rs & 0xFF000000) || !((~rs) & 0xFF000000))
        cpu->cycles += a ? 4 : 3;
    else
        cpu->cycles += a ? 5 : 4;

    cpu->fetch_seq = false;

    if (s) {
        cpu->Z_FLAG = !(*rd);
        cpu->N_FLAG = *rd >> 31;
    }
}

static void arm_multiply_long(arm7tdmi_t* cpu, u32 opcode) {
    bool u = (opcode >> 22) & 1;
    bool a = (opcode >> 21) & 1;
    bool s = (opcode >> 20) & 1;

    u32 rm = cpu->r[opcode & 0xF];
    u32 rs = cpu->r[(opcode >> 8) & 0xF];
    u32* rd_lo = &cpu->r[(opcode >> 12) & 0xF];
    u32* rd_hi = &cpu->r[(opcode >> 16) & 0xF];
    u64 result;

    cpu->fetch_seq = false;

    if (u)
        result = ((i64)(i32)rm) * ((i64)(i32)rs);
    else
        result = ((u64)rm) * ((u64)rs);

    if (a)
        result += (((u64)*rd_hi) << 32) | (u64)(*rd_lo);

    *rd_hi = result >> 32;
    *rd_lo = result;

    if (s) {
        cpu->Z_FLAG = !result;
        cpu->N_FLAG = result >> 63;
    }

    if (u) {
        if (!(rs & 0xFFFFFF00) || !((~rs) & 0xFFFFFF00))
            cpu->cycles += a ? 3 : 2;
        else if (!(rs & 0xFFFF0000) || !((~rs) & 0xFFFF0000))
            cpu->cycles += a ? 4 : 3;
        else if (!(rs & 0xFF000000) || !((~rs) & 0xFF000000))
            cpu->cycles += a ? 5 : 4;
        else
            cpu->cycles += a ? 6 : 5;   
    } else {
        if (!(rs & 0xFFFFFF00))
            cpu->cycles += a ? 3 : 2;
        else if (!(rs & 0xFFFF0000))
            cpu->cycles += a ? 4 : 3;
        else if (!(rs & 0xFF000000))
            cpu->cycles += a ? 5 : 4;
        else
            cpu->cycles += a ? 6 : 5;  
    }
}
